effect.shader:
float gmHash(float n){return fract(sin(n)*43758.5453123);}
float gmNoise(float x){float i=floor(x),f=fract(x);f=f*f*(3.0-2.0*f);return mix(gmHash(i),gmHash(i+1.0),f)*2.0-1.0;}
float gmArc(float x,float phase){float n=gmNoise(x*detail+phase);n+=gmNoise(x*detail*2.07+phase*1.31)*0.5;n+=gmNoise(x*detail*4.13+phase*1.73)*0.25;return n/1.75;}
void main(){vec4 src=texture2DCv(inputImg.texture,acScreenNorm);vec2 p=acLayerNorm-0.5;p.x*=acLayerSize.x/max(acLayerSize.y,1.0);p.y*=-1.0;vec2 a=start/1000.0,b=end/1000.0;vec2 ab=b-a;float len=max(length(ab),0.0001);vec2 dir=ab/len,nor=vec2(-dir.y,dir.x);vec2 rel=p-a;float x=dot(rel,dir)/len;float y=dot(rel,nor);float phase=floor(acTime*speed*6.0)/6.0+seed*13.17;float mainPath=gmArc(x,phase)*displacement*sin(clamp(x,0.0,1.0)*3.14159265);float clipMask=step(0.0,x)*step(x,progress);float d=abs(y-mainPath);float branchD=999.0;for(int i=0;i<3;i++){float fi=float(i);float origin=0.18+0.22*fi+0.08*gmHash(seed+fi*7.0);float side=gmHash(seed+fi*19.0)>0.5?1.0:-1.0;float bx=max(x-origin,0.0);float branchPath=mainPath+side*bx*(0.18+0.08*fi)+gmArc(x,phase+31.0+fi*9.0)*displacement*0.45;float gate=step(origin,x)*step(x,min(origin+0.42,progress))*branches;branchD=min(branchD,mix(999.0,abs(y-branchPath),gate));}d=min(d,branchD);float px=1.0/max(acLayerSize.y,1.0);float core=exp(-d/max(widthPx*px,0.0001));float glow=exp(-d/max(glowPx*px,0.0001));float hot=pow(core,3.0);float pulse=1.0+(gmHash(floor(acTime*speed*12.0)+seed)-0.5)*2.0*flicker;vec3 energy=(coreColor.rgb*hot*2.5+glowColor.rgb*(core+glow*0.75))*clipMask*intensity*pulse;vec3 outRgb=1.0-(1.0-src.rgb)*(1.0-clamp(energy,0.0,1.0));outRgb+=max(energy-1.0,0.0);gl_FragColor=vec4(outRgb,src.a);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
